INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00045000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 45), 'unit45-lesson1', 'Common Phrasal Verbs: Meanings and Examples', 'Phrasal verbs are combinations of a verb and a preposition or adverb that create a meaning different from the original verb. Here are 25 common phrasal verbs with their meanings and examples.', $${"details":[{"concept":"bow to","explanation":"To yield or give in to pressure or demands.","example":"The company president finally bowed to pressure and resigned. / The government had to bow to public pressure. / I can't agree with you but I bow to your greater experience and knowledge.","burmese":"အလျော့ပေးရသည်၊ လက်လွှတ်ရသည်။"},{"concept":"break down","explanation":"To stop working (of a machine), or to deteriorate (of health or a situation).","example":"Her health broke down under the pressure of work. / The machine must break down at this busy hour. / His van broke down.","burmese":"(စက်)ပျက်သည်။ (ကိစ္စမရှိတဲ့အခြေအနေ)ယိုယွင်းသည်။"},{"concept":"call on","explanation":"To appeal to or ask someone to do something; to visit someone.","example":"The human rights group has called on the US to end the death penalty. / We sometimes have to call on outside expertise. / The President paid a courtesy call on Emperor Akihito.","burmese":"ပန်ကြားသည်၊ အမှတ်ရပ်ခံသည်။"},{"concept":"chum up","explanation":"To become close friends with someone.","example":"She chummed up with some girls from Bristol on holiday. / They chummed up in a short time. / It's good to see your children chumming up with mine so well.","burmese":"အပြင်းအသင်းဖြစ်သည်။"},{"concept":"cross out","explanation":"To draw a line through a word or words to show they are wrong or not needed.","example":"He could cross out half the words because they were unnecessary. / Two sentences were crossed out. / He crossed out three wrong words.","burmese":"စာလုံး မကျက် ခြစ်ပစ်သည်။"},{"concept":"flick through","explanation":"To look through something quickly, browsing casually.","example":"In bookshop, I picked up a novel by a new writer and began to flick through it. / I had a quick flick through your report. / I had a flick through the catalogue while I was waiting.","burmese":"လှန်လှန်ကြည့်သည်။"},{"concept":"figure out","explanation":"To understand, solve, or calculate something.","example":"I couldn't figure out what the teacher was talking about. / Please figure out the total cost. / We must figure out how to solve the problem.","burmese":"သဘောပေါက်သည်၊ နားလည်သည်၊ တွက်ချက်သည်။"},{"concept":"go for sth","explanation":"To choose something or try to achieve something.","example":"I think I'll go for the steak. What are you having? / I think I will go for the fruit salad. / She is going for the world record in the high jump.","burmese":"ရွေးချယ်သည်၊ ရယူရန် ကြိုးစားသည်။"},{"concept":"go after","explanation":"To chase or pursue someone or something.","example":"He went after the burglars. / Go after him and apologize. / He goes after every woman he meets.","burmese":"လိုက်သည်။"},{"concept":"get back at","explanation":"To get revenge on someone for something they did.","example":"She was trying to get back at him for humiliating her. / I will get back at him one day. / He will get back at you for this.","burmese":"ကလည်စေချင်သည်။"},{"concept":"hand in","explanation":"To submit or give something to someone in authority.","example":"I need to hand in my homework tomorrow. / Please hand in the document to me. / We handed in a letter of protest.","burmese":"တင်သပ်သည်၊ အပ်အပ်သည်၊ အပ်နှံသည်။"},{"concept":"hinge on","explanation":"To depend on something for its success or outcome.","example":"My decision will hinge on your views. / The answers hinge on supply and demand. / But elections hinge on shorter-term concerns.","burmese":"တည်သည်။"},{"concept":"look back","explanation":"To think about something in the past.","example":"Stop spending your time looking back. Live your life now and enjoy every moment! / Adults often look back on their childhood as a golden age. / When I look back I can see where we went wrong.","burmese":"ပြန်လည်တူးဆွဲကြည့်သည်။"},{"concept":"look after","explanation":"To take care of someone or something.","example":"We look after the neighbours' cat while they are away. / I will look after her child when she is on a business trip. / It is a tradition that the young look after the old in their family.","burmese":"ကြည့်ရှုစောင့်ရှောက်သည်။"},{"concept":"look round","explanation":"To go around a place and look at things.","example":"Let's look round this museum slowly. I think it will be interesting. / Let's look round the town this afternoon. / Have a look round the shop.","burmese":"လှည့်ပတ်ကြည့်သည်။"},{"concept":"look down on","explanation":"To consider someone as being inferior or less important.","example":"She looks down on anyone who hasn't had a university education. / You should never look down on poor people. / Never look down on yourself.","burmese":"အထင်အမြင်သေးသည်။"},{"concept":"look forward to","explanation":"To feel excited and pleased about something that is going to happen.","example":"We look forward to hearing from you soon. / I always look forward to getting home to my wife and children. / I look forward to seeing you again.","burmese":"မျှော်လင့်စောင့်စားသည်။"},{"concept":"pull down","explanation":"To demolish or destroy a building.","example":"The old warehouse has been pulled down. / It is easier to pull down than build. / The house was pulled down and the site redeveloped.","burmese":"ဖျက်ချသည်။"},{"concept":"read on","explanation":"To continue reading.","example":"Please read on to the end of the chapter. / I took a book with me to read on the train. / If you like a good story, read on.","burmese":"ဆက်ဖတ်သည်။"},{"concept":"read out","explanation":"To read something aloud to others.","example":"He began to read out loud. / She read out the letters to all of us. / He read out the names of all the winners.","burmese":"ဖတ်ပြသည်။"},{"concept":"sum up","explanation":"To give a brief summary of something.","example":"I can't sum up his whole philosophy in one sentence. / To sum up, there are three main ways of tackling the problem... / You have only 100 words in which to sum up his speech.","burmese":"အကျဉ်းချုပ်သည်။"},{"concept":"shape up","explanation":"To improve or develop in a satisfactory way.","example":"I have been told that if I don't shape up, I will lose my job. / He will shape up into an excellent basketball player. / Mark didn't shape up until he was thirty years old.","burmese":"တိုးတက်အားကောင်းစေသည်။"},{"concept":"tell off","explanation":"To scold or reprimand someone.","example":"The pupil was told off for being careless. / My parents told me off for coming home late. / They were told off to clean the latrines.","burmese":"ဆူသည်၊ ကန့်သတ်သည်။"},{"concept":"wear off","explanation":"To gradually disappear or diminish.","example":"The pain is slowly wearing off. / The effects of the drug were wearing off. / After the effectiveness of the vaccines wears off, the risk of actual infection returns.","burmese":"တဖြည်းဖြည်းချင် ပျက်ပြယ်သွားသည်။"},{"concept":"wipe out","explanation":"To completely destroy or eliminate something.","example":"The government is trying to wipe out drug trafficking. / One dose of penicillin can wipe out the infection. / The plague once could wipe out a village.","burmese":"ချမ်းနှိမ်သည်၊ တိုက်ဖျက်သည်။"}]}$$::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00045000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 45), 'unit45-ex1', 'multiple_choice', 'Choose the correct meaning or usage of the phrasal verb.', $$[{"id":4501,"question":"What does 'bow to' mean?","options":["ပန်ကြားသည်၊ အမှတ်ရပ်ခံသည်။","အလျော့ပေးရသည်၊ လက်လွှတ်ရသည်။","အပြင်းအသင်းဖြစ်သည်။"],"answer":"အလျော့ပေးရသည်၊ လက်လွှတ်ရသည်။","explanation":"'bow to' means to yield or give in to pressure. 'bow to' ဆိုတာ အလျော့ပေးရတာ၊ လက်လွှတ်ရတာကို ဆိုလိုပါတယ်။","points":1},{"id":4502,"question":"Which phrasal verb means '(စက်)ပျက်သည်။ (ကိစ္စမရှိတဲ့အခြေအနေ)ယိုယွင်းသည်။'?","options":["pull down","wipe out","break down"],"answer":"break down","explanation":"'break down' means a machine stops working or a situation deteriorates. 'break down' ဆိုတာ စက်ပျက်တာ သို့မဟုတ် အခြေအနေယိုယွင်းတာကို ဆိုလိုပါတယ်။","points":1},{"id":4503,"question":"The company president finally ___ to pressure and resigned.","options":["chummed","bowed","hinged"],"answer":"bowed","explanation":"'bowed to pressure' means he yielded to the pressure. 'bowed to pressure' ဆိုတာ ဖိအားကို အလျော့ပေးတာကို ဆိုလိုပါတယ်။","points":1},{"id":4504,"question":"What does 'call on' mean?","options":["ဆူသည်၊ ကန့်သတ်သည်။","ပန်ကြားသည်၊ အမှတ်ရပ်ခံသည်။","လှည့်ပတ်ကြည့်သည်။"],"answer":"ပန်ကြားသည်၊ အမှတ်ရပ်ခံသည်။","explanation":"'call on' means to appeal to or ask someone to do something. 'call on' ဆိုတာ ပန်ကြားတာ၊ အမှတ်ရပ်ခံတာကို ဆိုလိုပါတယ်။","points":1},{"id":4505,"question":"Which phrasal verb means 'အပြင်းအသင်းဖြစ်သည်။'?","options":["go after","get back at","chum up"],"answer":"chum up","explanation":"'chum up' means to become close friends. 'chum up' ဆိုတာ အပြင်းအသင်းဖြစ်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4506,"question":"He could ___ half the words because they were unnecessary.","options":["flick through","cross out","read on"],"answer":"cross out","explanation":"'cross out' means to draw a line through words to show they are not needed. 'cross out' ဆိုတာ စာလုံးတွေကို ခြစ်ပစ်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4507,"question":"What does 'flick through' mean?","options":["လှန်လှန်ကြည့်သည်။","ဖတ်ပြသည်။","ဆက်ဖတ်သည်။"],"answer":"လှန်လှန်ကြည့်သည်။","explanation":"'flick through' means to look through something quickly. 'flick through' ဆိုတာ လှန်လှန်ကြည့်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4508,"question":"I couldn't ___ what the teacher was talking about.","options":["look back","figure out","sum up"],"answer":"figure out","explanation":"'figure out' means to understand or solve something. 'figure out' ဆိုတာ နားလည်တာ၊ တွက်ချက်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4509,"question":"Which phrasal verb means 'ရွေးချယ်သည်၊ ရယူရန် ကြိုးစားသည်။'?","options":["go after","go for sth","get back at"],"answer":"go for sth","explanation":"'go for sth' means to choose or try to achieve something. 'go for sth' ဆိုတာ ရွေးချယ်တာ၊ ရယူဖို့ ကြိုးစားတာကို ဆိုလိုပါတယ်။","points":1},{"id":4510,"question":"He ___ the burglars.","options":["bowed to","chummed up","went after"],"answer":"went after","explanation":"'went after' means to chase or pursue someone. 'went after' ဆိုတာ လိုက်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4511,"question":"What does 'get back at' mean?","options":["ကလည်စေချင်သည်။","ဖျက်ချသည်။","တင်သပ်သည်၊ အပ်နှံသည်။"],"answer":"ကလည်စေချင်သည်။","explanation":"'get back at' means to get revenge on someone. 'get back at' ဆိုတာ ကလည်စေချင်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4512,"question":"I need to ___ my homework tomorrow.","options":["wipe out","hand in","read on"],"answer":"hand in","explanation":"'hand in' means to submit or give something to someone. 'hand in' ဆိုတာ တင်သပ်တာ၊ အပ်နှံတာကို ဆိုလိုပါတယ်။","points":1},{"id":4513,"question":"My decision will ___ your views.","options":["look down on","hinge on","look forward to"],"answer":"hinge on","explanation":"'hinge on' means to depend on something. 'hinge on' ဆိုတာ တည်တာ၊ မူတည်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4514,"question":"What does 'look back' mean?","options":["လှည့်ပတ်ကြည့်သည်။","ပြန်လည်တူးဆွဲကြည့်သည်။","ကြည့်ရှုစောင့်ရှောက်သည်။"],"answer":"ပြန်လည်တူးဆွဲကြည့်သည်။","explanation":"'look back' means to think about something in the past. 'look back' ဆိုတာ ပြန်လည်တူးဆွဲကြည့်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4515,"question":"We ___ the neighbours' cat while they are away.","options":["look round","look down on","look after"],"answer":"look after","explanation":"'look after' means to take care of someone or something. 'look after' ဆိုတာ ကြည့်ရှုစောင့်ရှောက်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4516,"question":"Which phrasal verb means 'လှည့်ပတ်ကြည့်သည်။'?","options":["look round","look after","look back"],"answer":"look round","explanation":"'look round' means to go around a place and look at things. 'look round' ဆိုတာ လှည့်ပတ်ကြည့်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4517,"question":"She ___ anyone who hasn't had a university education.","options":["looks forward to","looks down on","looks after"],"answer":"looks down on","explanation":"'look down on' means to consider someone as inferior. 'look down on' ဆိုတာ အထင်အမြင်သေးတာကို ဆိုလိုပါတယ်။","points":1},{"id":4518,"question":"What does 'look forward to' mean?","options":["အထင်အမြင်သေးသည်။","မျှော်လင့်စောင့်စားသည်။","ပြန်လည်တူးဆွဲကြည့်သည်။"],"answer":"မျှော်လင့်စောင့်စားသည်။","explanation":"'look forward to' means to feel excited about something coming. 'look forward to' ဆိုတာ မျှော်လင့်စောင့်စားတာကို ဆိုလိုပါတယ်။","points":1},{"id":4519,"question":"The old warehouse has been ___.","options":["wiped out","shaped up","pulled down"],"answer":"pulled down","explanation":"'pull down' means to demolish a building. 'pull down' ဆိုတာ ဖျက်ချတာကို ဆိုလိုပါတယ်။","points":1},{"id":4520,"question":"What does 'wipe out' mean?","options":["အကျဉ်းချုပ်သည်။","ချမ်းနှိမ်သည်၊ တိုက်ဖျက်သည်။","တိုးတက်အားကောင်းစေသည်။"],"answer":"ချမ်းနှိမ်သည်၊ တိုက်ဖျက်သည်။","explanation":"'wipe out' means to completely destroy or eliminate something. 'wipe out' ဆိုတာ ချမ်းနှိမ်တာ၊ တိုက်ဖျက်တာကို ဆိုလိုပါတယ်။","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 46: Idioms
-- --------------------------------------------------------------------------

INSERT INTO units (id, unit_number, title, lesson_count, exercise_count, question_count)
VALUES ('00000046-0000-4000-8000-000000000001', 46, 'Idioms', 1, 1, 20)
ON CONFLICT (unit_number) DO UPDATE SET
  id = EXCLUDED.id,
  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00046000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 46), 'unit46-lesson1', 'Idioms: Common English Idioms', 'Idioms are expressions that have a figurative meaning different from their literal meaning. Learning common idioms helps you understand native English speakers and express yourself more naturally.', $${"details":[{"concept":"walk of life","explanation":"A person's occupation, status, or social class. Used in the phrase 'all walks of life' to mean people from many different backgrounds.","example":"She has friends from all walks of life.","burmese":"'walk of life' ဆိုတာ လူတစ်ယောက်ရဲ့ အလုပ်၊ လူမှုအဆင့်အတန်းကို ဆိုလိုပါတယ်။"},{"concept":"a piece of cake","explanation":"Something very easy to do. Used to describe tasks that require little effort.","example":"The exam was a piece of cake.","burmese":"'a piece of cake' ဆိုတာ အလွယ်တကူ လုပ်နိုင်တဲ့ အရာကို ဆိုလိုပါတယ်။"},{"concept":"a penny for your thoughts","explanation":"A gentle way to ask someone what they are thinking about, especially when they are quiet.","example":"You have been quiet all morning, a penny for your thoughts?","burmese":"'a penny for your thoughts' ဆိုတာ တစ်ယောက်ယောက် ဘာတွေတွေးနေလဲ မေးတဲ့ နည်းလမ်းပါ။"},{"concept":"all smiles","explanation":"Very happy and smiling. Used to describe someone who is showing great happiness.","example":"She was all smiles at the news of her win.","burmese":"'all smiles' ဆိုတာ ပျော်ပျော်ပန်းပန်း ရှိနေတာကို ဆိုလိုပါတယ်။"},{"concept":"black sheep","explanation":"A person who is considered a disgrace or failure by their family or group.","example":"My brother is the black sheep of the family.","burmese":"'black sheep' ဆိုတာ မိသားစုရဲ့ စိတ်နှောင့်ရှက်ဖွယ်လူကို ဆိုလိုပါတယ်။"},{"concept":"break the ice","explanation":"To initiate a conversation or ease tension in a social situation, especially when people are meeting for the first time.","example":"She sent him a text to break the ice.","burmese":"'break the ice' ဆိုတာ ပထမဆုံးတွေ့တဲ့အခါ စကားစပြပြီး ရင်းနှီးအောင်လုပ်တာပါ။"},{"concept":"child's play","explanation":"Something very easy to do; something that requires little skill or effort.","example":"The test was real child's play.","burmese":"'child's play' ဆိုတာ အလွန်လွယ်ကူတဲ့ အရာကို ဆိုလိုပါတယ်။"},{"concept":"crocodile tears","explanation":"Fake or insincere tears; pretending to be sad when you are not really sad.","example":"Don't soften your heart; he was shedding crocodile tears.","burmese":"'crocodile tears' ဆိုတာ ဟန်ဆောင်ပြီးငိုတာကို ဆိုလိုပါတယ်။"},{"concept":"foot the bill","explanation":"To pay for something; to cover the cost of something.","example":"Who's going to foot the bill for the damage?","burmese":"'foot the bill' ဆိုတာ ကုန်ကျစရိတ်ကို ပေးဆောင်တာပါ။"},{"concept":"get rid of","explanation":"To remove, throw away, or eliminate something unwanted.","example":"It is difficult to get rid of insects.","burmese":"'get rid of' ဆိုတာ မလိုချင်တဲ့အရာကို ဖယ်ရှားပစ်တာပါ။"},{"concept":"get a grip","explanation":"To control oneself or a situation; to calm down and behave sensibly.","example":"Get a grip on yourself!","burmese":"'get a grip' ဆိုတာ ကိုယ့်ကိုယ်ကို ထိန်းချုပ်တာပါ။"},{"concept":"go through the roof","explanation":"To become extremely angry or furious about something.","example":"Mom will go through the roof when she finds out we disobeyed her again.","burmese":"'go through the roof' ဆိုတာ အလွန်ဒေါသထွက်တာကို ဆိုလိုပါတယ်။"},{"concept":"I'm afraid","explanation":"A polite way to express that something is not possible or to deliver bad news.","example":"I'm afraid we can't come.","burmese":"'I'm afraid' ဆိုတာ စိတ်မကောင်းစွာ ငြင်းဆိုတဲ့ ယဉ်ကျေးတဲ့ ပုံစံပါ။"},{"concept":"leave it at that","explanation":"To stop talking about something; to accept the current situation and not continue further.","example":"We will never agree, so let's just leave it at that.","burmese":"'leave it at that' ဆိုတာ ဒီလောက်ပဲထားလိုက်ကြပါလို့ ဆိုလိုပါတယ်။"},{"concept":"not at all","explanation":"A polite response to thanks, meaning 'you're welcome'; also means 'not in any way'.","example":"Thank you for all your help. Not at all.","burmese":"'not at all' ဆိုတာ ကျေးဇူးတင်တဲ့အခါ ပြန်ဖြေတဲ့ ယဉ်ကျေးတဲ့ စကားပါ။"},{"concept":"on the spot","explanation":"Immediately; right away; at that very moment without delay.","example":"The policeman arrested the thief on the spot.","burmese":"'on the spot' ဆိုတာ ချက်ချင်း၊ ချိန်ချိန်ဆဆ ဆိုလိုပါတယ်။"},{"concept":"off colour","explanation":"Feeling unwell, slightly ill, or not in one's usual good health.","example":"You look a little off colour today.","burmese":"'off colour' ဆိုတာ နမကောင်းဖြစ်နေတာကို ဆိုလိုပါတယ်။"},{"concept":"over the moon","explanation":"Extremely happy and delighted about something.","example":"She's over the moon about her new job.","burmese":"'over the moon' ဆိုတာ အလွန်ပျော်ရွှင်နေတာကို ဆိုလိုပါတယ်။"},{"concept":"once in a blue moon","explanation":"Very rarely; almost never; something that happens extremely infrequently.","example":"I see her once in a blue moon.","burmese":"'once in a blue moon' ဆိုတာ အလွန်ရှားရှားဖြစ်ဖြစ် ဖြစ်တာကို ဆိုလိုပါတယ်။"},{"concept":"out of the blue","explanation":"Unexpectedly; without warning; completely surprising.","example":"His resignation came out of the blue.","burmese":"'out of the blue' ဆိုတာ မမျှော်လင့်ဘဲ ဖြစ်လာတာကို ဆိုလိုပါတယ်။"},{"concept":"pie in the sky","explanation":"An unrealistic or impossible hope or plan; a dream that is unlikely to come true.","example":"His dream to become President is just a pie in the sky.","burmese":"'pie in the sky' ဆိုတာ မဖြစ်နိုင်တဲ့ မျှော်လင့်ချက်ကို ဆိုလိုပါတယ်။"}]}$$::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00046000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 46), 'unit46-ex1', 'multiple_choice', 'Choose the correct meaning of the idiom.', $$[{"id":4601,"question":"What does 'a piece of cake' mean?","options":["something very easy to do","a delicious dessert","a small portion of food"],"answer":"something very easy to do","explanation":"'A piece of cake' means something very easy to do. 'a piece of cake' ဆိုတာ အလွယ်တကူလုပ်နိုင်တဲ့ အရာကို ဆိုလိုပါတယ်။","points":1},{"id":4602,"question":"What does 'black sheep' mean?","options":["a fast runner","a person who is considered a disgrace or failure by their family","a quiet person"],"answer":"a person who is considered a disgrace or failure by their family","explanation":"'Black sheep' refers to a person who is considered a disgrace or failure by their family or group. 'black sheep' ဆိုတာ မိသားစုရဲ့ စိတ်နှောင့်ရှက်ဖွယ်လူကို ဆိုလိုပါတယ်။","points":1},{"id":4603,"question":"What does 'all smiles' mean?","options":["feeling sad","very happy and smiling","wearing makeup"],"answer":"very happy and smiling","explanation":"'All smiles' means very happy and smiling. 'all smiles' ဆိုတာ ပျော်ပျော်ပန်းပန်း ရှိနေတာကို ဆိုလိုပါတယ်။","points":1},{"id":4604,"question":"What does 'break the ice' mean?","options":["to freeze water","to initiate a conversation or ease tension","to stop talking"],"answer":"to initiate a conversation or ease tension","explanation":"'Break the ice' means to initiate a conversation or ease tension in a social situation. 'break the ice' ဆိုတာ ပထမဆုံးတွေ့တဲ့အခါ စကားစပြပြီး ရင်းနှီးအောင်လုပ်တာပါ။","points":1},{"id":4605,"question":"What does 'foot the bill' mean?","options":["to walk quickly","to pay for something","to kick something"],"answer":"to pay for something","explanation":"'Foot the bill' means to pay for something; to cover the cost. 'foot the bill' ဆိုတာ ကုန်ကျစရိတ်ကို ပေးဆောင်တာပါ။","points":1},{"id":4606,"question":"What does 'over the moon' mean?","options":["very high up","extremely happy and delighted","confused"],"answer":"extremely happy and delighted","explanation":"'Over the moon' means extremely happy and delighted about something. 'over the moon' ဆိုတာ အလွန်ပျော်ရွှင်နေတာကို ဆိုလိုပါတယ်။","points":1},{"id":4607,"question":"What does 'crocodile tears' mean?","options":["real sadness","fake or insincere tears","tears from an animal"],"answer":"fake or insincere tears","explanation":"'Crocodile tears' means fake or insincere tears; pretending to be sad. 'crocodile tears' ဆိုတာ ဟန်ဆောင်ပြီးငိုတာကို ဆိုလိုပါတယ်။","points":1},{"id":4608,"question":"What does 'get a grip' mean?","options":["to hold something tightly","to control oneself or a situation","to slip and fall"],"answer":"to control oneself or a situation","explanation":"'Get a grip' means to control oneself or a situation; to calm down. 'get a grip' ဆိုတာ ကိုယ့်ကိုယ်ကို ထိန်းချုပ်တာပါ။","points":1},{"id":4609,"question":"What does 'go through the roof' mean?","options":["to climb a building","to become extremely angry","to escape quickly"],"answer":"to become extremely angry","explanation":"'Go through the roof' means to become extremely angry or furious. 'go through the roof' ဆိုတာ အလွန်ဒေါသထွက်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4610,"question":"What does 'pie in the sky' mean?","options":["a type of dessert","an unrealistic or impossible hope","a beautiful view"],"answer":"an unrealistic or impossible hope","explanation":"'Pie in the sky' means an unrealistic or impossible hope or plan. 'pie in the sky' ဆိုတာ မဖြစ်နိုင်တဲ့ မျှော်လင့်ချက်ကို ဆိုလိုပါတယ်။","points":1},{"id":4611,"question":"What does 'once in a blue moon' mean?","options":["every night","very rarely or almost never","once a month"],"answer":"very rarely or almost never","explanation":"'Once in a blue moon' means very rarely; almost never. 'once in a blue moon' ဆိုတာ အလွန်ရှားရှားဖြစ်ဖြစ် ဖြစ်တာကို ဆိုလိုပါတယ်။","points":1},{"id":4612,"question":"What does 'out of the blue' mean?","options":["from the sky","unexpectedly or without warning","in the morning"],"answer":"unexpectedly or without warning","explanation":"'Out of the blue' means unexpectedly; without warning; completely surprising. 'out of the blue' ဆိုတာ မမျှော်လင့်ဘဲ ဖြစ်လာတာကို ဆိုလိုပါတယ်။","points":1},{"id":4613,"question":"What does 'get rid of' mean?","options":["to find something","to remove or throw away something unwanted","to hide something"],"answer":"to remove or throw away something unwanted","explanation":"'Get rid of' means to remove, throw away, or eliminate something unwanted. 'get rid of' ဆိုတာ မလိုချင်တဲ့အရာကို ဖယ်ရှားပစ်တာပါ။","points":1},{"id":4614,"question":"What does 'off colour' mean?","options":["wearing colorful clothes","feeling unwell or slightly ill","angry"],"answer":"feeling unwell or slightly ill","explanation":"'Off colour' means feeling unwell, slightly ill, or not in one's usual good health. 'off colour' ဆိုတာ နမကောင်းဖြစ်နေတာကို ဆိုလိုပါတယ်။","points":1},{"id":4615,"question":"What does 'on the spot' mean?","options":["in a specific place","immediately or right away","on a dirty surface"],"answer":"immediately or right away","explanation":"'On the spot' means immediately; right away; at that very moment. 'on the spot' ဆိုတာ ချက်ချင်း၊ ချိန်ချိန်ဆဆ ဆိုလိုပါတယ်။","points":1},{"id":4616,"question":"What does 'leave it at that' mean?","options":["to forget about something","to stop talking about something or accept the current situation","to put something down"],"answer":"to stop talking about something or accept the current situation","explanation":"'Leave it at that' means to stop talking about something; to accept the current situation. 'leave it at that' ဆိုတာ ဒီလောက်ပဲထားလိုက်ကြပါလို့ ဆိုလိုပါတယ်။","points":1},{"id":4617,"question":"What does 'walk of life' mean?","options":["a walking path","a person's occupation, status, or social class","a type of exercise"],"answer":"a person's occupation, status, or social class","explanation":"'Walk of life' refers to a person's occupation, status, or social class. 'walk of life' ဆိုတာ လူတစ်ယောက်ရဲ့ အလုပ်၊ လူမှုအဆင့်အတန်းကို ဆိုလိုပါတယ်။","points":1},{"id":4618,"question":"What does 'a penny for your thoughts' mean?","options":["an offer to buy something cheap","a way to ask someone what they are thinking","a request for money"],"answer":"a way to ask someone what they are thinking","explanation":"'A penny for your thoughts' is a gentle way to ask someone what they are thinking about. 'a penny for your thoughts' ဆိုတာ တစ်ယောက်ယောက် ဘာတွေတွေးနေလဲ မေးတဲ့ နည်းလမ်းပါ။","points":1},{"id":4619,"question":"What does 'not at all' mean?","options":["completely disagree","a polite response to thanks; not in any way","very tired"],"answer":"a polite response to thanks; not in any way","explanation":"'Not at all' is a polite response to thanks, meaning 'you're welcome'; also means 'not in any way'. 'not at all' ဆိုတာ ကျေးဇူးတင်တဲ့အခါ ပြန်ဖြေတဲ့ ယဉ်ကျေးတဲ့ စကားပါ။","points":1},{"id":4620,"question":"What does 'child's play' mean?","options":["a children's game","something very easy to do","a toy"],"answer":"something very easy to do","explanation":"'Child's play' means something very easy to do. 'a piece of cake' has the same meaning. 'child's play' ဆိုတာ အလွန်လွယ်ကူတဲ့ အရာကို ဆိုလိုပါတယ်။","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

